css:
.loader {
  width: 150px;
  height: 214px;
  padding: 15px;
  background: #f5f5f5;
  border: 1px solid #eee;
  border-radius: 12px;
  position: relative;
  overflow: hidden;
}

.header {
  display: flex;
  margin-top: 5px;
  margin-bottom: 20px;
}

.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #e0e0e0;
  margin-right: 15px;
}

.info {
  flex: 1;
  padding-top: 5px;
}

.nickname {
  width: 40px;
  height: 16px;
  background: #e0e0e0;
  border-radius: 4px;
  margin-bottom: 8px;
}
.signature {
  width: 55px;
  height: 12px;
  background: #e0e0e0;
  border-radius: 4px;
}

.qr-code {
  width: 110px;
  height: 110px;
  background: #e0e0e0;
  border-radius: 8px;
  margin: 0 auto;
  position: relative;
  overflow: hidden;
}
.qr-icon {
  width: 80px;
  height: 80px;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  opacity: 0.08;
}

.loader::after {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 50%;
  height: 100%;
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0) 0%,
    rgba(255, 255, 255, 0.3) 50%,
    rgba(255, 255, 255, 0) 100%
  );
  animation: shine 1.2s infinite;
}

@keyframes shine {
  100% {
    left: 200%;
  }
}
